CREATE TABLE result AS SELECT episodeview.c12 AS c12,path.strPath AS strPath,tvshowview.c00 AS c00,tvshowview.c01 AS c01,tvshowview.c05 AS c05,tvshowview.c08 AS c08,tvshowview.c14 AS c14,tvshowview.c13 AS c13,seasons.idSeason AS idSeason,count(1) AS nrow,count(files.playCount) AS nplayed FROM episodeview JOIN tvshowview ON tvshowview.idShow=episodeview.idShow JOIN seasons ON seasons.idShow=tvshowview.idShow AND seasons.season=episodeview.c12 JOIN files ON files.idFile=episodeview.idFile JOIN tvshowlinkpath ON tvshowlinkpath.idShow=tvshowview.idShow JOIN path ON path.idPath=tvshowlinkpath.idPath WHERE tvshowview.idShow=1 GROUP BY episodeview.c12;